/// <summary>
/// The MCP tools call the same endpoint methods as the HTTP API: this turns their results into the tool's JSON
/// answer, or into an error the assistant can read and correct (validation, not found, conflicts, business rules).
/// </summary>
internal static class McpResults
{
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);

    /// <summary>DataAnnotations of the request, as the HTTP endpoints check them (400).</summary>
    public static void Validate(object request)
    {
        ArgumentNullException.ThrowIfNull(request);
        var errors = new List<ValidationResult>();
        if (!Validator.TryValidateObject(request, new ValidationContext(request), errors, validateAllProperties: true))
        {
            throw new McpException("Datos no válidos: " + string.Join("; ", errors.Select(e => e.ErrorMessage)));
        }
    }

    public static string ToJson(IResult result)
    {
        ArgumentNullException.ThrowIfNull(result);
        if (result is INestedHttpResult nested)
        {
            result = nested.Result;
        }

        var status = (result as IStatusCodeHttpResult)?.StatusCode ?? StatusCodes.Status200OK;
        var value = (result as IValueHttpResult)?.Value;
        if (status >= 400)
        {
            throw new McpException(value switch
            {
                HttpValidationProblemDetails validation => $"{status} {validation.Title}: " +
                    string.Join("; ", validation.Errors.Select(e => $"{e.Key}: {string.Join(" ", e.Value)}")),
                ProblemDetails problem => $"{status} {problem.Title}: {problem.Detail}",
                _ => status == StatusCodes.Status404NotFound ? "404: no existe." : $"Error {status}.",
            });
        }

        return value is null ? JsonSerializer.Serialize(new { status }, Json) : JsonSerializer.Serialize(value, value.GetType(), Json);
    }
